function optionsFor(p,user=C.pin.gm,phase=p.checkpoint.phase,suffix='0'){return {packetId:'packet-'+suffix,segmentId:'segment-'+suffix,userId:user,phase,bootstrapMacroUuid:p.checkpoint.resources.find(r=>r.kind==='Macro')?.uuid??resources(p.batch,p.mode).find(r=>r.kind==='Macro').uuid};}
function packet(p,user=C.pin.gm,phase=p.checkpoint.phase){return admittedControllerInputs(p,optionsFor(p,user,phase));}
function activeEmpty(mode='synthetic'){const p=observedPlan(mode);p.checkpoint=copy(pending().checkpoint);const backup={kind:'backup-manifest',batch:p.batch,source:p.mode,value:{synthetic:true}};p.baseline.backupManifestSha256=sha(JSON.stringify(backup));return p;}
function localSegment(issued){const p=issued.packet;return {packetId:p.anchor.packetId,segmentId:p.anchor.segmentId,parentRevision:p.anchor.revision,parentCheckpointSha256:p.anchor.checkpointSha256,packetSha256:sha(issued.packetBytes),identity:identityFor(p.audience.userId),runtime:p.runtime.map(r=>({...r,served:r.packaged})),navigation:{timeOrigin:1000,type:'navigate'},events:[],mutations:[],captures:[],controlState:{phase:p.phase,resources:copy(p.resources),mappings:copy(p.mappings),packMappings:copy(p.packMappings)},firstFailure:null};}
function event(s,kind,value){const sequence=s.events.length;if(kind==='operation')s.events.push({sequence,kind,value:copy(value)});else{const array=kind==='mutation'?s.mutations:s.captures,index=array.length;array.push(copy(value));s.events.push({sequence,kind,index});}}
async function setupChain(mode='synthetic'){const p=activeEmpty(mode),issued=await issue(p,optionsFor(p)),s=localSegment(issued),full=observedPlan(mode).checkpoint;s.controlState={phase:'gm',resources:copy(full.resources),mappings:copy(full.mappings),packMappings:copy(full.packMappings)};const remaining=[...full.resources],known=new Set();while(remaining.length){const n=remaining.findIndex(r=>!r.parentUuid||known.has(r.parentUuid));assert.ok(n>=0);const r=remaining.splice(n,1)[0];event(s,'mutation',full.mutations.find(m=>m.kind==='create'&&m.uuid===r.uuid));known.add(r.uuid);}event(s,'operation',full.operations[0]);for(const m of full.mutations.filter(m=>m.kind!=='create'))event(s,'mutation',m);event(s,'operation',full.operations[1]);assert.deepEqual(admittedControllerSegmentErrors(s,issued.packet),[]);return {issued,segment:s,plan:await merge(issued.plan,s)};}
async function captureSegment(plan,caseId,suffix){const user=caseId.startsWith('gm-')?C.pin.gm:C.pin.player,issued=await issue(plan,optionsFor(plan,user,caseId.includes('reload')?'reload':user===C.pin.gm?'gm':'player',suffix)),s=localSegment(issued),c=await capture(plan,caseId);s.navigation=copy(c.navigation);event(s,'operation',{kind:'resume',userId:user,navigation:copy(s.navigation)});event(s,'operation',{kind:'begin',caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied});event(s,'capture',c);return {issued,segment:s,plan:await merge(issued.plan,s)};}

test('private host serially merges GM/player/reload segments without publishing aggregate captures',async()=>{let {plan}=await setupChain();const gm=await captureSegment(plan,'gm-trainer-core-to-optional','gm');plan=gm.plan;const player=await captureSegment(plan,'player-trainer-review','player');assert.doesNotMatch(player.issued.packetBytes,/gm-trainer-core-to-optional.*summary|beforeSha256|PRIVATE/);assert.equal(player.segment.captures.length,1);assert.equal(player.segment.captures[0].identity.user,C.pin.player);const reload=await captureSegment(player.plan,'player-reload-preservation','reload');assert.equal(reload.plan.handoff.revision,4);assert.equal(reload.plan.checkpoint.captures.length,3);assert.deepEqual(reload.plan.checkpoint.captures.slice(0,2),player.plan.checkpoint.captures);assert.deepEqual(errors(reload.plan),[]);});
test('packet validators reject private plans and nested private fields at every public entry',async()=>{assert.ok(publicAdmittedPacketErrors(observedPlan()).length);const base=await packet(observedPlan());for(const mutate of [p=>p.baseline={},p=>p.resources[0].private={},p=>p.controlReceipts[0].private={},p=>p.runtime[0].private={},p=>p.mappings[0].source.private={},p=>p.audience.private={},p=>p.resume.captures=[],p=>p.baselineChecks.ids=[]]){const p=copy(base);mutate(p);assert.ok(publicAdmittedPacketErrors(p).length);}const p=copy(base);p.resources[0]=null;assert.ok(publicAdmittedPacketErrors(p).length);});
test('serial issue refuses forked or unacknowledged handoffs and native pre-created fixtures',async()=>{const p=activeEmpty(),i=await issue(p,optionsFor(p));assert.deepEqual((await issue(i.plan,optionsFor(p))).plan,i.plan);await assert.rejects(issue(i.plan,optionsFor(p,C.pin.gm,'initial','fork')),/outstanding/);await assert.rejects(issue(observedPlan('native'),optionsFor(observedPlan('native'))),/before fixture/);await assert.rejects(issue(pending(),{}),/held/);});
test('identical accepted bytes are idempotent; reused IDs, stale parent and changed baseline fail',async()=>{const {issued,segment,plan}=await setupChain();assert.deepEqual(await merge(plan,segment),plan);const changed=copy(segment);changed.navigation.timeOrigin++;await assert.rejects(merge(plan,changed),/different bytes/);for(const mutate of [p=>p.baseline.settings[0].value.changed=true,p=>p.checkpoint.phase='cleanup']){const p=copy(issued.plan);mutate(p);await assert.rejects(merge(p,segment),/baseline\/history|stale/);}const s=copy(segment);s.parentRevision++;await assert.rejects(merge(issued.plan,s),/anchor/);await assert.rejects(merge(issued.plan,segment,{segmentBytes:JSON.stringify({...segment,firstFailure:{reason:'substitution'}})}),/semantic/);});
test('local event order, identity and player GM-mutation substitution are rejected',async()=>{const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','p')),s=localSegment(i);for(const mutate of [s=>s.identity.user=C.pin.gm,s=>s.identity.private={},s=>event(s,'mutation',{kind:'access',uuid:s.controlState.resources[0].uuid,userId:C.pin.gm,batch:plan.batch,principal:C.pin.player,level:0}),s=>event(s,'operation',null),s=>s.events.push({sequence:1,kind:'operation',value:{kind:'macro-deleted'}}),s=>s.controlState.resources.reverse()]){const bad=copy(s);mutate(bad);assert.ok(admittedControllerSegmentErrors(bad,i.packet).length);await assert.rejects(merge(i.plan,bad));}});
test('first failure remains private and sticky through acknowledgements and subsequent cleanup',async()=>{const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','failure')),s=localSegment(i);event(s,'operation',{kind:'failure',reason:'PRIVATE-FAILURE-DETAIL'});s.firstFailure={reason:'PRIVATE-FAILURE-DETAIL'};const merged=await merge(i.plan,s),next=await issue(merged,optionsFor(merged,C.pin.gm,'cleanup','cleanup'));assert.equal(next.packet.resume.stopLatched,true);assert.equal(next.packet.resume.firstFailureRef,sha(s.firstFailure));assert.doesNotMatch(next.packetBytes,/PRIVATE-FAILURE-DETAIL/);const clear=copy(s);clear.firstFailure=null;await assert.rejects(merge(i.plan,clear),/failure/);const cleanup=localSegment(next);event(cleanup,'operation',{kind:'failure',reason:'Second failure'});cleanup.firstFailure={reason:'Second failure'};const final=await merge(next.plan,cleanup);assert.deepEqual(final.checkpoint.failure,s.firstFailure);});
test('bootstrap absence requires an out-of-record verifier before any claim/tag',async()=>{const p=activeEmpty('native'),config=await packet(p),uuid=config.baselineChecks.bootstrapMacroUuid,macro={documentName:'Macro',uuid,id:uuid.split('.')[1],author:{id:C.pin.gm},ownership:{default:0,[C.pin.gm]:3},getFlag:()=>undefined};const calls=[];assert.throws(()=>verifyFeatureReviewBootstrap(config,identityFor(C.pin.gm),macro,x=>{calls.push(x.operation);if(x.operation==='verify-private-macro-absence')throw Error('Private baseline absence not verified');}),/absence not verified/);assert.deepEqual(calls,['bootstrap-macro','verify-private-macro-absence']);p.baseline.ids.macros.push(macro.id);p.baseline.protectedDocuments.push({collection:'macros',id:macro.id,data:{_id:macro.id}});await assert.rejects(packet(p),/privately excluded/);});
test('refresh requires private acknowledgement, preserves failures and retains actual document object identity',async()=>{const {plan}=await setupChain('native'),first=await captureSegment(plan,'player-trainer-review','p1'),next=await issue(first.plan,optionsFor(first.plan,C.pin.player,'player','p2'));const retained=[{nativeReference:{marker:'Do not serialize/recreate'}}],exported={segment:first.segment,sha256:sha(JSON.stringify(first.segment)),eventCount:first.segment.events.length},args={packet:first.issued.packet,next:next.packet,exported,localEventCount:exported.eventCount,pendingReview:false,identity:identityFor(C.pin.player),verifyExecution:()=>{},packetSha256:sha(next.packetBytes)};const value=await refreshFeatureReviewPacket(args,retained);assert.equal(value.retainedReferences,retained);assert.equal(value.retainedReferences[0],retained[0]);await assert.rejects(refreshFeatureReviewPacket({...args,verifyExecution:()=>{throw Error('Missing private acknowledgement');}},retained),/acknowledgement/);await assert.rejects(refreshFeatureReviewPacket({...args,localEventCount:999},retained),/unexported/);await assert.rejects(refreshFeatureReviewPacket({...args,pendingReview:true},retained),/unfinished/);await assert.rejects(refreshFeatureReviewPacket({...args,next:first.issued.packet},retained),/stale/);});
test('private replay binds all segment bytes and rejects aggregate edits or missing raw segments',()=>temp(async dir=>{let {plan}=await setupChain();plan=(await captureSegment(plan,'gm-trainer-core-to-optional','g')).plan;await rawProofs(dir,plan);for(let n=0;n<plan.handoff.acceptedSegments.length;n++){const a=plan.handoff.acceptedSegments[n],path=`raw/segment-${n}.json`;await fs.writeFile(join(dir,path),a.segmentBytes);plan.evidence.raw.push({kind:'controller-segment',private:true,path,sha256:a.segmentSha256});}let result=await check(plan,{rawDirectory:dir});assert.equal(result.integrity,'passed',result.errors.join('; '));assert.equal(result.controllerReplay,'passed');assert.equal(result.nativeCases.passed,0);const edited=copy(plan);edited.checkpoint.operations.push({kind:'macro-deleted'});assert.equal((await check(edited,{rawDirectory:dir})).controllerReplay,'failed');plan.evidence.raw.pop();assert.equal((await check(plan,{rawDirectory:dir})).integrity,'failed');}));

test('compendium commitment tampering cannot be merged against the privately issued packet',async()=>{const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','configuration'));i.plan.handoff.issued.packet.baselineChecks.packConfigurationSha256='b'.repeat(64);i.plan.handoff.issued.packetBytes=JSON.stringify(i.plan.handoff.issued.packet);i.plan.handoff.issued.packetSha256=sha(i.plan.handoff.issued.packetBytes);const s=localSegment({packet:i.plan.handoff.issued.packet,packetBytes:i.plan.handoff.issued.packetBytes});await assert.rejects(merge(i.plan,s),/differs from latest/);});
test('local failed segments cannot continue cases and player segments cannot invent GM operations',async()=>{const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','stopped')),s=localSegment(i),c=await capture(plan,'player-trainer-review');event(s,'operation',{kind:'failure',reason:'Stop now'});s.firstFailure={reason:'Stop now'};event(s,'operation',{kind:'begin',caseId:c.caseId,status:c.summary.launchStatus,bodyExecuted:c.summary.bodyExecuted,resolutionDenied:c.summary.resolutionDenied});event(s,'capture',c);assert.ok(admittedControllerSegmentErrors(s,i.packet).some(e=>e.includes('stopped')));const bad=localSegment(i);event(bad,'operation',{kind:'macro-deleted'});assert.ok(admittedControllerSegmentErrors(bad,i.packet).some(e=>e.includes('GM operations')));});
test('malformed private handoff structures and non-JSON segment fields fail without proof IO',async()=>{for(const handoff of [null,{},[],{revision:0,issued:null,acceptedSegments:[null],genesisCheckpoint:null}]){const p=observedPlan();p.handoff=handoff;assert.ok(errors(p).length);assert.equal((await check(p)).integrity,'failed');}const {plan}=await setupChain(),i=await issue(plan,optionsFor(plan,C.pin.player,'player','malformed'));for(const mutate of [s=>s.runtime[0]=null,s=>s.events=[null],s=>s.controlState=null,s=>s.navigation=null,s=>s.identity=null,s=>s.events=[{sequence:0,kind:'operation',value:null}]]){const s=localSegment(i);mutate(s);assert.ok(admittedControllerSegmentErrors(s,i.packet).length);}});
test('actual player controller initializes and exports only local observations with public input',async()=>{const {plan}=await setupChain('native');plan.baseline.protectedDocuments[0].data.name='PRIVATE-DOCUMENT-CANARY';plan.baseline.settings[0].value.canary='PRIVATE-SETTING-CANARY';plan.baseline.users[0].permissions.canary='PRIVATE-USER-CANARY';const gm=await captureSegment(plan,'gm-trainer-core-to-optional','gm-private');gm.plan.checkpoint.captures[0].dom={text:'PRIVATE-GM-CAPTURE-CANARY'};gm.plan.checkpoint.operations.push({kind:'checkpoint',snapshot:{canary:'PRIVATE-GM-OPERATION-CANARY'}});const inputs=await packet(gm.plan,C.pin.player,'player'),source=await fs.readFile(new URL('../tools/foundry-feature-review-check.mjs',import.meta.url),'utf8'),contractUrl=new URL('../tools/feature-review-admitted-contract.mjs',import.meta.url).href,registryUrl=new URL('../src/util/rule-version-registry.js',import.meta.url).href,unusedLauncher='data:text/javascript,export function launchFeatureAcquisitionReview(){throw Error(%22No native case in this double%22)}';const isolatedSource=source.replace("'./feature-review-admitted-contract.mjs'",JSON.stringify(contractUrl)).replace("'/systems/ptu/src/module/apps/feature-acquisition-review-launcher.js'",JSON.stringify(unusedLauncher)).replace("'/systems/ptu/src/util/rule-version-registry.js'",JSON.stringify(registryUrl));const isolated=await import('data:text/javascript;base64,'+Buffer.from(isolatedSource).toString('base64')),names=['game','fetch','Dialog'],saved=Object.fromEntries(names.map(n=>[n,Object.getOwnPropertyDescriptor(globalThis,n)]));let output='';const html={find:()=>({val:v=>{if(v!==undefined)output=v;},on:()=>{}})};try{Object.defineProperty(globalThis,'game',{configurable:true,value:{world:{id:C.pin.world,title:C.target.title},version:C.pin.core,system:{id:'ptu',version:C.pin.system},user:{id:C.pin.player,isGM:false},users:copy(C.accounts.users),settings:{get:(scope,key)=>key==='worldSchemaVersion'?0.115:key==='worldSystemVersion'?'4.4.3':{}}}});Object.defineProperty(globalThis,'fetch',{configurable:true,value:async url=>({ok:true,arrayBuffer:async()=>Buffer.from((await fs.readFile(new URL('../'+url.replace('/systems/ptu/',''),import.meta.url),'utf8')).replace(/\r\n/g,'\n'))})});Object.defineProperty(globalThis,'Dialog',{configurable:true,value:class{constructor(config){this.config=config;this.element=html;}render(){this.config.render(html);}}});const controller=await isolated.openFeatureReviewCheck({inputs,verifyExecution:()=>{}}),segment=await controller.exportSegment();assert.equal(segment.identity.user,C.pin.player);assert.deepEqual(segment.captures,[]);assert.deepEqual(segment.mutations,[]);assert.equal(segment.events.length,1);assert.equal(segment.events[0].value.kind,'resume');assert.doesNotMatch(output,/PRIVATE-|gm-trainer-core-to-optional|protectedDocuments|baselineIds/);assert.deepEqual(JSON.parse(output),segment);}finally{for(const name of names)if(saved[name])Object.defineProperty(globalThis,name,saved[name]);else delete globalThis[name];}});
